// Replays trace.json (generated by `node packages/cli/dist/index.js trace`). The page never
// computes run state itself: every node state shown here was produced by the core reducer.
// The only derived marks are presentational: which edges have their condition met, which
// nodes changed since the previous step, and which node an attempt belongs to.

const SVG_NS = "http://www.w3.org/2000/svg";
const PLAY_INTERVAL_MS = 1400;
const MIN_BOARD_COLUMNS = 3;
const NARROW = window.matchMedia("(max-width: 640px)");

/** Board geometry, in SVG units. Wide boards flow left to right, narrow ones top to bottom. */
const WIDE = { nodeWidth: 256, nodeHeight: 104, rankGap: 80, siblingGap: 28, margin: 20 };
const TALL = { nodeWidth: 172, nodeHeight: 116, rankGap: 64, siblingGap: 16, margin: 20 };

const view = { trace: null, scenario: null, step: 0, timer: null };

const byId = (id) => document.getElementById(id);

function svg(tag, attributes = {}, text) {
  const element = document.createElementNS(SVG_NS, tag);
  for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, String(value));
  if (text !== undefined) element.textContent = text;
  return element;
}

function html(tag, attributes = {}, ...children) {
  const element = document.createElement(tag);
  for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, String(value));
  element.append(...children);
  return element;
}

/** A lamp glyph from the sprite in index.html. */
function lamp(symbol, attributes = {}) {
  const element = svg("svg", { class: "glyph", "aria-hidden": "true", focusable: "false", ...attributes });
  element.append(svg("use", { href: `#lamp-${symbol}` }));
  return element;
}

/** Lamp for a node: execution progress and result trust folded into one signal. */
function lampState(node) {
  if (node.execution === "cancelled") return "cancelled";
  if (node.execution === "failed" || node.execution === "exhausted" || node.disposition === "rejected") {
    return "failed";
  }
  if (node.disposition === "accepted") return "accepted";
  if (node.execution === "result_ready") return "unverified";
  if (node.execution === "running") return "running";
  if (node.execution === "ready") return "ready";
  return "pending";
}

const words = (value) => value.replaceAll("_", " ");

function describeNode(node) {
  const parts = [words(node.execution)];
  if (node.disposition !== null) parts.push(node.disposition);
  if (node.failureCategory !== null) parts.push(words(node.failureCategory));
  return parts;
}

/** Whether an edge's condition holds, read straight from the source node's snapshot. */
function edgeMet(edge, step) {
  const source = step.nodes[edge.from];
  if (edge.condition === "accepted") return source.disposition === "accepted";
  return source.execution === "result_ready" && source.disposition !== "rejected";
}

/** Ranks by longest path from a root, siblings by declaration order. */
function layout(graph, geometry, tall) {
  const rank = new Map(graph.nodes.map((node) => [node.id, 0]));
  let changed = true;
  while (changed) {
    changed = false;
    for (const edge of graph.edges) {
      const next = rank.get(edge.from) + 1;
      if (next > rank.get(edge.to)) {
        rank.set(edge.to, next);
        changed = true;
      }
    }
  }
  const { nodeWidth, nodeHeight, rankGap, siblingGap, margin } = geometry;
  const rankStep = (tall ? nodeHeight : nodeWidth) + rankGap;
  const siblingStep = (tall ? nodeWidth : nodeHeight) + siblingGap;
  const siblings = new Map();
  const slots = new Map();
  for (const node of graph.nodes) {
    const r = rank.get(node.id);
    const s = siblings.get(r) ?? 0;
    siblings.set(r, s + 1);
    slots.set(node.id, { rank: r, sibling: s });
  }
  const ranks = Math.max(...rank.values()) + 1;
  const widest = Math.max(...siblings.values());
  // Wide boards keep at least three ranks so every scenario renders at the same scale.
  const boardRanks = tall ? ranks : Math.max(ranks, MIN_BOARD_COLUMNS);
  const rankOffset = ((boardRanks - ranks) * rankStep) / 2;
  const positions = new Map();
  for (const [id, slot] of slots) {
    // Centre each rank's siblings across the widest rank.
    const siblingOffset = ((widest - siblings.get(slot.rank)) * siblingStep) / 2;
    const along = margin + rankOffset + slot.rank * rankStep;
    const across = margin + siblingOffset + slot.sibling * siblingStep;
    positions.set(id, tall ? { x: across, y: along } : { x: along, y: across });
  }
  const alongSize = margin * 2 + boardRanks * rankStep - rankGap;
  const acrossSize = margin * 2 + widest * siblingStep - siblingGap;
  return tall
    ? { positions, width: acrossSize, height: alongSize }
    : { positions, width: alongSize, height: acrossSize };
}

/** Squeeze a text element into `max` units if its content would overflow. */
function fit(element, max, unitsPerChar) {
  if (element.textContent.length * unitsPerChar > max) {
    element.setAttribute("textLength", max);
    element.setAttribute("lengthAdjust", "spacingAndGlyphs");
  }
  return element;
}

function renderGraph(scenario, step, previous) {
  const tall = NARROW.matches;
  const geometry = tall ? TALL : WIDE;
  const { nodeWidth: w, nodeHeight: h } = geometry;
  const graph = scenario.graph;
  const { positions, width, height } = layout(graph, geometry, tall);
  const root = byId("graph");
  root.replaceChildren();
  root.setAttribute("viewBox", `0 0 ${width} ${height}`);
  root.setAttribute("class", tall ? "tall" : "wide");
  // Tall boards never scale up, so a single column of nodes does not push the step off screen.
  root.style.maxWidth = tall ? `${width}px` : "";

  const defs = svg("defs");
  for (const lit of [false, true]) {
    const marker = svg("marker", {
      id: lit ? "arrow-lit" : "arrow",
      viewBox: "0 0 10 10",
      refX: 8,
      refY: 5,
      markerWidth: 5,
      markerHeight: 5,
      orient: "auto-start-reverse",
    });
    marker.append(svg("path", { d: "M 0 0 L 10 5 L 0 10 z", class: lit ? "arrow lit" : "arrow" }));
    defs.append(marker);
  }
  root.append(defs);

  for (const edge of graph.edges) {
    const from = positions.get(edge.from);
    const to = positions.get(edge.to);
    const lit = edgeMet(edge, step);
    const label = edge.condition === "result_ready" ? "RESULT" : "ACCEPTED";
    let d;
    let labelAt;
    if (tall) {
      const [x1, y1, x2, y2] = [from.x + w / 2, from.y + h, to.x + w / 2, to.y - 3];
      const bend = (y2 - y1) / 2;
      d = `M ${x1} ${y1} C ${x1} ${y1 + bend}, ${x2} ${y2 - bend}, ${x2} ${y2}`;
      // Put the label on the side the track bends away from, so converging labels never collide.
      labelAt = x2 > x1 ? { x: x1 - 10, y: y1 + 20, anchor: "end" } : { x: x1 + 10, y: y1 + 20, anchor: "start" };
    } else {
      const [x1, y1, x2, y2] = [from.x + w, from.y + h / 2, to.x - 3, to.y + h / 2];
      const bend = (x2 - x1) / 2;
      d = `M ${x1} ${y1} C ${x1 + bend} ${y1}, ${x2 - bend} ${y2}, ${x2} ${y2}`;
      // Label the edge where it leaves its source: above a level or falling edge, below a rising one.
      labelAt = { x: x1 + 12, y: y2 < y1 ? y1 + 22 : y1 - 11, anchor: "start" };
    }
    const kind = edge.condition === "result_ready" ? "result-ready" : "accepted";
    root.append(
      svg("path", {
        d,
        class: `track ${kind}${lit ? " lit" : ""}`,
        "marker-end": `url(#${lit ? "arrow-lit" : "arrow"})`,
      }),
      svg("text", { x: labelAt.x, y: labelAt.y, "text-anchor": labelAt.anchor, class: "track-label" }, label),
    );
  }

  const spoken = [];
  for (const spec of graph.nodes) {
    const node = step.nodes[spec.id];
    const before = previous?.nodes[spec.id];
    const changed = before !== undefined && JSON.stringify(before) !== JSON.stringify(node);
    const { x, y } = positions.get(spec.id);
    const state = describeNode(node);
    const attempts = node.attemptCount === 1 ? "1 attempt" : `${node.attemptCount} attempts`;
    const meta = `${spec.role} · ${attempts}`.toUpperCase();
    const group = svg("g", { class: `node${changed ? " changed" : ""}`, transform: `translate(${x} ${y})` });
    group.append(
      svg("title", {}, `${spec.id}: ${spec.objective}`),
      svg("rect", { width: w, height: h, rx: 2, class: "node-plate" }),
    );
    const glyph = svg("use", { href: `#lamp-${lampState(node)}`, class: "node-lamp" });
    if (tall) {
      glyph.setAttribute("x", 12);
      glyph.setAttribute("y", 12);
      glyph.setAttribute("width", 24);
      glyph.setAttribute("height", 24);
      group.append(
        glyph,
        fit(svg("text", { x: 44, y: 31, class: "node-name" }, spec.id), w - 54, 11.5),
        fit(svg("text", { x: 14, y: 61, class: "node-state" }, state[0]), w - 28, 8.8),
      );
      if (state.length > 1) {
        const rest = state.slice(1).join(" · ");
        group.append(fit(svg("text", { x: 14, y: 80, class: "node-state" }, rest), w - 28, 8.8));
      }
      group.append(fit(svg("text", { x: 14, y: 102, class: "node-meta" }, meta), w - 28, 8.2));
    } else {
      glyph.setAttribute("x", 14);
      glyph.setAttribute("y", 14);
      glyph.setAttribute("width", 26);
      glyph.setAttribute("height", 26);
      group.append(
        glyph,
        fit(svg("text", { x: 50, y: 35, class: "node-name" }, spec.id), w - 62, 13.2),
        fit(svg("text", { x: 16, y: 68, class: "node-state" }, state.join(" · ")), w - 32, 9.6),
        fit(svg("text", { x: 16, y: 90, class: "node-meta" }, meta), w - 32, 9),
      );
    }
    root.append(group);
    spoken.push(`${spec.id} ${state.join(", ")}`);
  }
  root.setAttribute("aria-label", `Task graph at step ${step.index + 1}: ${spoken.join("; ")}.`);
}

/** Middle-truncate content hashes so both ends stay recognisable. */
function shortValue(value) {
  const text = String(value);
  const hash = /^(sha256:)([0-9a-f]{64})$/.exec(text);
  return hash === null ? text : `${hash[1]}${hash[2].slice(0, 8)}…${hash[2].slice(-6)}`;
}

const FIELD_NAMES = { nodeId: "node", attemptId: "attempt", fencingToken: "fencing token" };

/** The node an event concerns: named on the event, or found through its attempt's dispatch. */
function eventSubject(scenario, event) {
  if (typeof event.nodeId === "string") return event.nodeId;
  if (typeof event.attemptId === "string") {
    for (const step of scenario.steps) {
      for (const command of step.commands) {
        if (command.type === "dispatch" && command.attemptId === event.attemptId) return command.nodeId;
      }
    }
  }
  return "run";
}

function elapsed(scenario, step) {
  const seconds = Math.round((Date.parse(step.event.at) - Date.parse(scenario.steps[0].event.at)) / 1000);
  return `+${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

function nodeChanges(scenario, step, previous) {
  if (previous === undefined) return [];
  return scenario.graph.nodes
    .filter((spec) => JSON.stringify(previous.nodes[spec.id]) !== JSON.stringify(step.nodes[spec.id]))
    .map((spec) => spec.id);
}

function renderGauges(scenario, step) {
  const gauges = byId("gauges");
  const statusLamp = {
    running: "running",
    cancelling: "cancelled",
    succeeded: "accepted",
    failed: "failed",
    cancelled: "cancelled",
  };
  const run = html("dd", { class: `run-${step.run.status}` }, lamp(statusLamp[step.run.status] ?? "pending"));
  run.append(words(step.run.status));

  const { maxConcurrent, maxAttemptsPerNode } = scenario.policy;
  const slots = html("span", { class: "slots", "aria-hidden": "true" });
  for (let i = 0; i < maxConcurrent; i += 1) {
    slots.append(html("span", { class: i < step.run.permitsInUse ? "slot held" : "slot" }));
  }
  const permits = html("dd", {}, slots, `${step.run.permitsInUse} of ${maxConcurrent} in use`);

  const pair = (term, detail) => html("div", {}, html("dt", {}, term), detail);
  gauges.replaceChildren(
    pair("Run", run),
    pair("Permits", permits),
    pair("Attempts", html("dd", {}, `up to ${maxAttemptsPerNode} per node`)),
  );
}

function renderStep(scenario, step, previous) {
  const count = byId("step-count");
  count.replaceChildren(
    html("span", { class: "visually-hidden" }, "Step "),
    html("strong", {}, String(step.index + 1)),
    ` / ${scenario.steps.length}`,
  );
  byId("step-event").textContent = step.event.type;
  byId("step-note").textContent = step.note;

  const verdict = byId("verdict");
  const changes = nodeChanges(scenario, step, previous);
  if (step.outcome === "applied") {
    verdict.className = "verdict";
    let detail = changes.length === 0 ? "No node changed state." : `Changed: ${changes.join(", ")}.`;
    if (previous === undefined) detail = "Run started.";
    verdict.replaceChildren(
      html("p", { class: "verdict-label" }, "Applied"),
      html("p", { class: "verdict-detail" }, detail),
    );
  } else {
    verdict.className = "verdict rejected";
    const label = html("p", { class: "verdict-label" }, lamp("failed"), "Rejected: ");
    label.append(html("code", {}, step.rejection.code));
    const unchanged = changes.length === 0 && previous?.run.status === step.run.status ? " Run state unchanged." : "";
    verdict.replaceChildren(label, html("p", { class: "verdict-detail" }, `${step.rejection.message}.${unchanged}`));
  }

  byId("event-json").textContent = JSON.stringify(step.event, null, 2);

  const commands = byId("commands");
  commands.replaceChildren();
  if (step.commands.length === 0) {
    commands.append(html("li", { class: "none" }, "None. The reducer is waiting for the next event."));
  }
  for (const command of step.commands) {
    const { type, ...rest } = command;
    const fields = html("dl");
    for (const [key, value] of Object.entries(rest)) {
      const dd = html("dd", {}, shortValue(value));
      if (shortValue(value) !== String(value)) dd.setAttribute("title", String(value));
      fields.append(html("dt", {}, FIELD_NAMES[key] ?? words(key)), dd);
    }
    commands.append(html("li", { class: `command cmd-${type}` }, html("p", { class: "command-type" }, type), fields));
  }
}

function renderJournal(scenario) {
  const list = byId("journal");
  list.replaceChildren();
  for (const step of scenario.steps) {
    const classes = ["entry"];
    if (step.outcome === "rejected") classes.push("rejected");
    if (step.index > view.step) classes.push("future");
    const verdict = html("span", { class: "entry-verdict" });
    if (step.outcome === "rejected") {
      verdict.append(lamp("failed"), html("code", {}, step.rejection.code));
    } else {
      verdict.append("applied");
    }
    const button = html(
      "button",
      { type: "button", class: classes.join(" "), "data-focus": `entry-${step.index}` },
      html("span", { class: "entry-no" }, String(step.index + 1).padStart(2, "0")),
      html("span", { class: "entry-time" }, elapsed(scenario, step)),
      html("span", { class: "entry-type" }, step.event.type),
      html("span", { class: "entry-node" }, eventSubject(scenario, step.event)),
      verdict,
    );
    if (step.index === view.step) button.setAttribute("aria-current", "step");
    button.addEventListener("click", () => {
      stopPlaying();
      go(scenario.id, step.index);
    });
    list.append(html("li", {}, button));
  }
  const rejected = scenario.steps.filter((step) => step.outcome === "rejected").length;
  byId("journal-tally").textContent =
    `${scenario.steps.length} events · ${scenario.steps.length - rejected} applied · ${rejected} rejected`;
}

/** "Retry and fencing: a crashed attempt, …" becomes a name and a description. */
function splitTitle(title) {
  const at = title.indexOf(": ");
  return at === -1 ? [title, ""] : [title.slice(0, at), title.slice(at + 2)];
}

function renderRoutes() {
  const list = byId("scenario-list");
  list.replaceChildren();
  view.trace.scenarios.forEach((scenario, index) => {
    const [name, description] = splitTitle(scenario.title);
    const rejected = scenario.steps.filter((step) => step.outcome === "rejected").length;
    const meta = html("span", { class: "route-meta" }, `${scenario.steps.length} events · `);
    if (rejected > 0) meta.append(html("span", { class: "count-rejected" }, `${rejected} rejected`), " · ");
    meta.append(`ends ${scenario.finalStatus}`);
    const link = html(
      "a",
      { class: "route", href: `#${scenario.id}/1`, "data-focus": `route-${index}` },
      html("span", { class: "route-no", "aria-hidden": "true" }, String(index + 1).padStart(2, "0")),
      html("span", { class: "route-name" }, name),
      html("span", { class: "route-desc" }, description),
      meta,
    );
    if (scenario.id === view.scenario.id) link.setAttribute("aria-current", "true");
    list.append(html("li", {}, link));
  });
}

function renderProvenance(scenario) {
  const applied = scenario.steps.filter((step) => step.outcome === "applied").length;
  const provenance = byId("provenance");
  provenance.replaceChildren(
    lamp(scenario.replayMatches ? "accepted" : "failed"),
    scenario.replayMatches
      ? `Replay check: replaying the ${applied} applied events from scratch reproduces the live state (final status ${scenario.finalStatus}).`
      : `Replay check failed: replaying the ${applied} applied events from scratch does not reproduce the live state.`,
  );
}

/** Re-rendering replaces the lists, so focus moves back to the rebuilt control with the same key. */
function restoreFocus(key) {
  if (key !== undefined) document.querySelector(`[data-focus="${key}"]`)?.focus();
}

function render() {
  const focused = document.activeElement?.dataset?.focus;
  const scenario = view.scenario;
  const step = scenario.steps[view.step];
  const previous = scenario.steps[view.step - 1];
  renderRoutes();
  byId("scenario-title").textContent = scenario.title;
  byId("scenario-summary").textContent = scenario.summary;
  renderGauges(scenario, step);
  renderGraph(scenario, step, previous);
  renderStep(scenario, step, previous);
  renderJournal(scenario);
  renderProvenance(scenario);
  byId("prev").disabled = view.step === 0;
  byId("next").disabled = view.step === scenario.steps.length - 1;
  restoreFocus(focused);
}

function go(scenarioId, stepIndex) {
  const scenario = view.trace.scenarios.find((candidate) => candidate.id === scenarioId) ?? view.trace.scenarios[0];
  view.scenario = scenario;
  view.step = Math.min(Math.max(stepIndex, 0), scenario.steps.length - 1);
  const hash = `#${scenario.id}/${view.step + 1}`;
  if (location.hash !== hash) history.replaceState(null, "", hash);
  render();
}

function stopPlaying() {
  if (view.timer !== null) clearInterval(view.timer);
  view.timer = null;
  const play = byId("play");
  play.textContent = "Play";
  play.setAttribute("aria-pressed", "false");
}

function togglePlay() {
  if (view.timer !== null) {
    stopPlaying();
    return;
  }
  if (view.step === view.scenario.steps.length - 1) go(view.scenario.id, 0);
  const play = byId("play");
  play.textContent = "Pause";
  play.setAttribute("aria-pressed", "true");
  view.timer = setInterval(() => {
    if (view.step >= view.scenario.steps.length - 1) {
      stopPlaying();
      return;
    }
    go(view.scenario.id, view.step + 1);
  }, PLAY_INTERVAL_MS);
}

function fromHash() {
  let hash = location.hash.slice(1);
  try {
    hash = decodeURIComponent(hash);
  } catch {
    // A mangled link (a stray "%") falls back to the raw text, which then matches no scenario.
  }
  const [id, step] = hash.split("/");
  return { id, step: Number.parseInt(step ?? "1", 10) - 1 || 0 };
}

function showLoadError(error) {
  const box = html(
    "div",
    { class: "load-error", role: "alert" },
    html("h2", {}, "The traces did not load"),
    html("p", {}, `trace.json could not be read: ${error.message}.`),
  );
  const hint = html("p", {}, "To view them locally, run ");
  hint.append(html("code", {}, "npm run site"), " and serve the ", html("code", {}, "site/"), " directory over HTTP.");
  box.append(hint);
  document.body.classList.remove("is-loading");
  byId("main").replaceChildren(box);
}

async function main() {
  try {
    const response = await fetch("trace.json");
    if (!response.ok) throw new Error(`the server answered HTTP ${response.status}`);
    view.trace = await response.json();
    if (!Array.isArray(view.trace.scenarios) || view.trace.scenarios.length === 0) {
      throw new Error("it contains no scenarios");
    }
  } catch (error) {
    showLoadError(error);
    return;
  }

  byId("prev").addEventListener("click", () => {
    stopPlaying();
    go(view.scenario.id, view.step - 1);
  });
  byId("next").addEventListener("click", () => {
    stopPlaying();
    go(view.scenario.id, view.step + 1);
  });
  byId("play").addEventListener("click", togglePlay);
  document.addEventListener("keydown", (event) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    if (event.target instanceof HTMLElement && event.target.closest("input, textarea, select, pre")) return;
    const targets = {
      ArrowRight: view.step + 1,
      ArrowLeft: view.step - 1,
      Home: 0,
      End: view.scenario.steps.length - 1,
    };
    if (!(event.key in targets)) return;
    event.preventDefault();
    stopPlaying();
    go(view.scenario.id, targets[event.key]);
  });
  // Follow the hash when it changes under an open page: back button, pasted links, scenario links.
  window.addEventListener("hashchange", () => {
    stopPlaying();
    const target = fromHash();
    go(target.id, target.step);
  });
  NARROW.addEventListener("change", render);

  document.body.classList.remove("is-loading");
  const initial = fromHash();
  go(initial.id, initial.step);
}

main();
